'use strict';

/**
 * dvly-oci-secrets — shared Lambda layer.
 *
 * Reads and writes secret values in the Oracle Cloud Infrastructure (OCI)
 * Vault Secrets API using OCI Signature v1 (RSA-SHA256). Results are cached
 * in-process (per Lambda container) to avoid a cross-cloud call + KMS round
 * trip on every invocation.
 *
 * Requires the following env vars (set on the consuming Lambda), unless
 * supplied via configure() overrides:
 *   OCI_TENANCY_OCID      tenancy OCID (ocid1.tenancy.oc1..)
 *   OCI_USER_OCID         dedicated OCI IAM user OCID (ocid1.user.oc1..)
 *   OCI_KEY_FINGERPRINT   fingerprint of the uploaded API key
 *   OCI_KEY_PEM_B64       base64 of the RSA private key PEM
 *                         OR OCI_KEY_FILE - path to the PEM inside the layer
 *   OCI_REGION            e.g. us-ashburn-1
 *   OCI_VAULT_OCID        vault OCID (ocid1.vault.oc1..) — for get/create by name
 *   OCI_COMPARTMENT_OCID  compartment OCID — for create
 *   OCI_KEY_ID            KMS master encryption key OCID — for create
 *   OCI_SECRET_OCID       default secret OCID for getSecret()
 *
 * API:
 *   configure(overrides)               -> void
 *   getSecret()                        -> Promise<string>  (value of OCI_SECRET_OCID)
 *   getSecretByOcid(ocid)              -> Promise<string>
 *   getSecretBundleByOcid(ocid)        -> Promise<object>
 *   getSecretByName(name)              -> Promise<string>
 *   getSecretBundleByName(name)        -> Promise<object>
 *   createOrUpdateSecret({ name, value, description, metadata }) -> Promise<object>
 *   clearCache()                       -> void
 *   isConfigValid()                    -> boolean
 */

const https = require('https');
const fs = require('fs');
const { signRequest } = require('./oci-signer');

const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

// Module-level overrides injected by the caller (e.g. a PEM fetched from SSM).
const _overrides = {};

function configure(overrides) {
  Object.assign(_overrides, overrides);
}

const cfg = () => {
  let privateKeyPem = _overrides.privateKeyPem;
  if (!privateKeyPem && process.env.OCI_KEY_PEM_B64) {
    privateKeyPem = Buffer.from(process.env.OCI_KEY_PEM_B64, 'base64').toString('utf8');
  } else if (!privateKeyPem && process.env.OCI_KEY_FILE && fs.existsSync(process.env.OCI_KEY_FILE)) {
    privateKeyPem = fs.readFileSync(process.env.OCI_KEY_FILE, 'utf8');
  }
  return {
    tenancyOcid: _overrides.tenancyOcid || process.env.OCI_TENANCY_OCID,
    userOcid: _overrides.userOcid || process.env.OCI_USER_OCID,
    fingerprint: _overrides.fingerprint || process.env.OCI_KEY_FINGERPRINT,
    privateKeyPem,
    region: _overrides.region || process.env.OCI_REGION || 'us-ashburn-1',
    secretOcid: _overrides.secretOcid || process.env.OCI_SECRET_OCID,
    vaultId: _overrides.vaultId || process.env.OCI_VAULT_OCID,
    compartmentId: _overrides.compartmentId || process.env.OCI_COMPARTMENT_OCID,
    keyId: _overrides.keyId || process.env.OCI_KEY_ID,
  };
};

const _cache = new Map(); // key -> { value, bundle, expiresAt }

function isConfigValid() {
  const c = cfg();
  return !!(c.tenancyOcid && c.userOcid && c.fingerprint && c.privateKeyPem && c.region);
}

function host() {
  return `secrets.vaults.${cfg().region}.oci.oraclecloud.com`;
}

function sign(c, method, path, body, query) {
  return signRequest({
    tenancyOcid: c.tenancyOcid,
    userOcid: c.userOcid,
    fingerprint: c.fingerprint,
    privateKeyPem: c.privateKeyPem,
    region: c.region,
    method,
    path,
    query,
    body,
    contentType: body !== undefined ? 'application/json' : undefined,
  });
}

function httpsRequest(hostname, path, headers, method, body) {
  return new Promise((resolve, reject) => {
    const req = https.request({ host: hostname, path, method, headers }, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          try { resolve(data ? JSON.parse(data) : {}); }
          catch (e) { reject(new Error(`OCI_INVALID_JSON: ${data.slice(0, 200)}`)); }
        } else {
          const err = new Error(`OCI_HTTP_${res.statusCode}: ${data.slice(0, 500)}`);
          err.statusCode = res.statusCode;
          reject(err);
        }
      });
    });
    req.on('error', reject);
    if (body !== undefined) req.end(Buffer.from(body, 'utf8'));
    else req.end();
  });
}

/**
 * Fetch the CURRENT secret bundle by secret OCID.
 * Endpoint: GET /20190301/secretbundles/{secretId}  (GetSecretBundle)
 */
async function fetchBundle(secretOcid) {
  if (!isConfigValid()) throw new Error('OCI_SECRETS_CONFIG_MISSING');
  const c = cfg();
  const path = `/20190301/secretbundles/${encodeURIComponent(secretOcid)}`;
  const { headers } = sign(c, 'GET', path);
  return httpsRequest(host(), path, headers, 'GET');
}

/**
 * Lookup the current secret bundle by name.
 * Endpoint: POST /20190301/secretbundles/actions/getByName
 */
async function fetchBundleByName(name) {
  const c = cfg();
  if (!isConfigValid() || !c.vaultId) throw new Error('OCI_SECRETS_CONFIG_MISSING');
  const qs = new URLSearchParams({ secretName: name, vaultId: c.vaultId });
  const path = `/20190301/secretbundles/actions/getByName?${qs.toString()}`;
  const { headers } = sign(c, 'POST', path, '');
  return httpsRequest(host(), path, headers, 'POST', '');
}

function bundleToString(bundle) {
  const content = bundle?.secretBundleContent || {};
  if (content.contentType === 'BASE64') {
    return Buffer.from(content.content || '', 'base64').toString('utf8');
  }
  if (content.contentType === 'PLAINTEXT') {
    return content.content || '';
  }
  throw new Error(`OCI_UNSUPPORTED_CONTENT_TYPE: ${content.contentType || 'none'}`);
}

function cached(key, fetcher) {
  const hit = _cache.get(key);
  if (hit && Date.now() < hit.expiresAt) return Promise.resolve(hit);
  return fetcher().then((bundle) => {
    const entry = { bundle, value: bundleToString(bundle), expiresAt: Date.now() + CACHE_TTL_MS };
    _cache.set(key, entry);
    return entry;
  });
}

async function getSecretBundleByOcid(secretOcid) {
  if (!secretOcid) throw new Error('OCI_SECRET_OCID_MISSING');
  return (await cached(`ocid:${secretOcid}`, () => fetchBundle(secretOcid))).bundle;
}

async function getSecretByOcid(secretOcid) {
  if (!secretOcid) throw new Error('OCI_SECRET_OCID_MISSING');
  return (await cached(`ocid:${secretOcid}`, () => fetchBundle(secretOcid))).value;
}

async function getSecretBundleByName(name) {
  const c = cfg();
  if (!c.vaultId) throw new Error('OCI_VAULT_OCID_MISSING');
  return (await cached(`name:${name}`, () => fetchBundleByName(name))).bundle;
}

async function getSecretByName(name) {
  const c = cfg();
  if (!c.vaultId) throw new Error('OCI_VAULT_OCID_MISSING');
  return (await cached(`name:${name}`, () => fetchBundleByName(name))).value;
}

/** Back-compat: value of the default OCI_SECRET_OCID. */
async function getSecret() {
  return getSecretByOcid(cfg().secretOcid);
}

/** Back-compat: bundle of the default OCI_SECRET_OCID. */
async function getSecretBundle() {
  return getSecretBundleByOcid(cfg().secretOcid);
}

async function createSecret({ name, value, description, metadata }) {
  const c = cfg();
  if (!isConfigValid() || !c.vaultId || !c.compartmentId || !c.keyId) {
    throw new Error('OCI_SECRETS_CREATE_CONFIG_MISSING');
  }
  const body = JSON.stringify({
    compartmentId: c.compartmentId,
    vaultId: c.vaultId,
    keyId: c.keyId,
    secretName: name,
    ...(description ? { description } : {}),
    ...(metadata ? { metadata } : {}),
    secretContent: {
      contentType: 'BASE64',
      content: Buffer.from(String(value), 'utf8').toString('base64'),
    },
  });
  const path = '/20190301/secrets';
  const { headers } = sign(c, 'POST', path, body);
  return httpsRequest(host(), path, headers, 'POST', body);
}

async function createSecretVersion(secretId, value) {
  const c = cfg();
  if (!isConfigValid()) throw new Error('OCI_SECRETS_CONFIG_MISSING');
  const body = JSON.stringify({
    ...(c.vaultId ? { vaultId: c.vaultId } : {}),
    secretContent: {
      contentType: 'BASE64',
      content: Buffer.from(String(value), 'utf8').toString('base64'),
    },
  });
  const path = `/20190301/secrets/${encodeURIComponent(secretId)}/versions`;
  const { headers } = sign(c, 'POST', path, body);
  return httpsRequest(host(), path, headers, 'POST', body);
}

/**
 * Create the secret, or if it already exists, add a new version with `value`.
 * Name must match OCI rules: [A-Za-z0-9._-], unique within the vault.
 */
async function createOrUpdateSecret({ name, value, description, metadata }) {
  try {
    const created = await createSecret({ name, value, description, metadata });
    _cache.delete(`name:${name}`);
    return created;
  } catch (err) {
    if (err && err.statusCode === 409) {
      const existing = await fetchBundleByName(name);
      if (!existing || !existing.secretId) throw err;
      const version = await createSecretVersion(existing.secretId, value);
      _cache.delete(`name:${name}`);
      return version;
    }
    throw err;
  }
}

function clearCache() { _cache.clear(); }

module.exports = {
  configure,
  getSecret,
  getSecretByOcid,
  getSecretBundle,
  getSecretBundleByOcid,
  getSecretByName,
  getSecretBundleByName,
  createOrUpdateSecret,
  clearCache,
  isConfigValid,
};
